# deps/build.jl
# using Pkg
# using Libdl

const REPO_URL = "https://github.com/cuddorg/cudd.git"
# const REPO_REF = "main"
const REPO_REF = "cudd-3.0.0"
const PREFIX   = joinpath(@__DIR__, "usr")
const LIBDIR   = joinpath(PREFIX, "lib")
const INCDIR   = joinpath(PREFIX, "include")
const SRCDIR   = joinpath(@__DIR__, "cudd-src")

const LIBNAME = Sys.iswindows() ? "cudd.dll" :
                Sys.isapple()  ? "libcudd.dylib" :
                                  "libcudd.so"

# library name for the wrapper
const WRAP_LIBNAME = Sys.iswindows() ? "libmycuddwrap.dll" :
                     Sys.isapple()  ? "libmycuddwrap.dylib" :
                                       "libmycuddwrap.so"

mkpath.( (PREFIX, LIBDIR, INCDIR) )
isdir(SRCDIR) && rm(SRCDIR; recursive=true, force=true)

run(`git clone --depth 1 --branch=$(REPO_REF) $(REPO_URL) $(SRCDIR)`)

cd(SRCDIR) do
    run(`autoreconf -fvi`)
    run(`./configure --enable-shared --disable-static CFLAGS=-O3\ -fPIC --prefix=$(PREFIX)`)
    run(`make -j$(Sys.CPU_THREADS) ACLOCAL=aclocal AUTOMAKE=automake AUTOCONF=autoconf`)
    run(`make install ACLOCAL=aclocal AUTOMAKE=automake AUTOCONF=autoconf`)
end

cc = get(ENV, "CC", Sys.iswindows() ? "gcc" : "cc")

wrap_src    = joinpath(@__DIR__, "mycudd_wrap.c")
wrap_out    = joinpath(LIBDIR, WRAP_LIBNAME)

# flags for compiling the wrapper
cmdstring = String[]

push!(cmdstring, "$cc")

if Sys.isapple()
    push!(cmdstring, "-dynamiclib")
    push!(cmdstring, "-fPIC")
elseif Sys.islinux()
    push!(cmdstring, "-shared")
    push!(cmdstring, "-fPIC")
elseif Sys.iswindows()
    push!(cmdstring, "-shared")
end

push!(cmdstring, "-I$(INCDIR)")
push!(cmdstring, "-I$(SRCDIR)")
push!(cmdstring, "-I$(joinpath(SRCDIR, "cudd"))")
push!(cmdstring, "-I$(joinpath(SRCDIR, "util"))")
push!(cmdstring, "-I$(joinpath(SRCDIR, "mtr"))")
push!(cmdstring, "-I$(joinpath(SRCDIR, "st"))")
push!(cmdstring, "-I$(joinpath(SRCDIR, "epd"))")

push!(cmdstring, wrap_src)
push!(cmdstring, "-L$(LIBDIR)")
push!(cmdstring, "-lcudd")
push!(cmdstring, "-o")
push!(cmdstring, wrap_out)

println("[MiniCUDD] building wrapper with: ", Cmd(cmdstring))
Cmd(cmdstring) |> run

open(joinpath(@__DIR__, "deps.jl"), "w") do io
    println(io, "# Auto-generated by deps/build.jl")
    println(io, "const libcudd_path = ", repr(joinpath(LIBDIR, LIBNAME)))
    println(io, "const mycuddwrap_path = ", repr(wrap_out))
end

println("[MiniCUDD] built: ", joinpath(LIBDIR, LIBNAME))
println("[MiniCUDD] built wrapper: ", wrap_out)
